use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

fn find(t: Tree, x: int) -> bool {
    let mut cur = t.root
    while cur != -1 {
        let k = t.keys[cur]
        if x == k {
            return true
        }
        if x < k {
            cur = t.lefts[cur]
        } else {
            cur = t.rights[cur]
        }
    }
    false
}

fn insert(t: Tree, x: int) -> bool {
    if find(t, x) {
        return false
    }
    let idx: int = t.keys.len() as int
    t.keys.push(x)
    t.lefts.push(-1)
    t.rights.push(-1)
    if t.root == -1 {
        t.root = idx
        return true
    }
    let mut cur = t.root
    loop {
        if x < t.keys[cur] {
            if t.lefts[cur] == -1 {
                t.lefts[cur] = idx
                break
            }
            cur = t.lefts[cur]
        } else {
            if t.rights[cur] == -1 {
                t.rights[cur] = idx
                break
            }
            cur = t.rights[cur]
        }
    }
    true
}

fn set_child(t: Tree, parent: int, was_left: bool, child: int) {
    if parent == -1 {
        t.root = child
    } else if was_left {
        t.lefts[parent] = child
    } else {
        t.rights[parent] = child
    }
}

fn delete(t: Tree, x: int) -> bool {
    let mut parent = -1
    let mut is_left = false
    let mut cur = t.root
    while cur != -1 && t.keys[cur] != x {
        parent = cur
        if x < t.keys[cur] {
            is_left = true
            cur = t.lefts[cur]
        } else {
            is_left = false
            cur = t.rights[cur]
        }
    }
    if cur == -1 {
        return false
    }
    let l = t.lefts[cur]
    let r = t.rights[cur]
    if l == -1 {
        set_child(t, parent, is_left, r)
    } else if r == -1 {
        set_child(t, parent, is_left, l)
    } else {
        let mut sp = cur
        let mut s = r
        while t.lefts[s] != -1 {
            sp = s
            s = t.lefts[s]
        }
        t.keys[cur] = t.keys[s]
        if sp == cur {
            t.rights[cur] = t.rights[s]
        } else {
            t.lefts[sp] = t.rights[s]
        }
    }
    true
}

fn inorder(t: Tree) -> string {
    let mut out: Vec<string> = []
    let mut stack: Vec<int> = []
    let mut cur = t.root
    while cur != -1 || stack.len() > 0 {
        while cur != -1 {
            stack.push(cur)
            cur = t.lefts[cur]
        }
        let n = stack.pop().unwrap_or(-1)
        out.push("${t.keys[n]}")
        cur = t.rights[n]
    }
    if out.len() == 0 {
        return "<empty>"
    }
    out.join(" ")
}

fn height(t: Tree) -> int {
    if t.root == -1 {
        return 0
    }
    let mut best = 0
    let mut nodes: Vec<int> = [t.root]
    let mut depths: Vec<int> = [1]
    while nodes.len() > 0 {
        let n = nodes.pop().unwrap_or(-1)
        let d = depths.pop().unwrap_or(0)
        if d > best {
            best = d
        }
        if t.lefts[n] != -1 {
            nodes.push(t.lefts[n])
            depths.push(d + 1)
        }
        if t.rights[n] != -1 {
            nodes.push(t.rights[n])
            depths.push(d + 1)
        }
    }
    best
}

fn main() {
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if insert(t, arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if find(t, arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if delete(t, arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(inorder(t))
        } else if cmd == "height" {
            println("${height(t)}")
        } else if cmd == "min" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c = t.root
                while t.lefts[c] != -1 {
                    c = t.lefts[c]
                }
                println("${t.keys[c]}")
            }
        } else if cmd == "max" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c = t.root
                while t.rights[c] != -1 {
                    c = t.rights[c]
                }
                println("${t.keys[c]}")
            }
        }
    }
}

